using FluentValidation;namespace SchoolERP.Application.Features.SchoolClasses;public sealed class CreateSchoolClassRequestValidator:AbstractValidator<CreateSchoolClassRequest>{public CreateSchoolClassRequestValidator(){RuleFor(x=>x.AcademicYearId).NotEmpty();RuleFor(x=>x.Name).NotEmpty().MaximumLength(150);RuleFor(x=>x.Code).NotEmpty().MaximumLength(50).Matches("^[A-Za-z0-9]+(?:[-_][A-Za-z0-9]+)*$");RuleFor(x=>x.ShortName).MaximumLength(50);RuleFor(x=>x.DisplayOrder).GreaterThanOrEqualTo(0);RuleFor(x=>x.EducationLevel).IsInEnum().When(x=>x.EducationLevel.HasValue);RuleFor(x=>x.Description).MaximumLength(500);}}public sealed class UpdateSchoolClassRequestValidator:AbstractValidator<UpdateSchoolClassRequest>{public UpdateSchoolClassRequestValidator(){RuleFor(x=>x.Name).NotEmpty().MaximumLength(150);RuleFor(x=>x.ShortName).MaximumLength(50);RuleFor(x=>x.DisplayOrder).GreaterThanOrEqualTo(0);RuleFor(x=>x.EducationLevel).IsInEnum().When(x=>x.EducationLevel.HasValue);RuleFor(x=>x.Description).MaximumLength(500);}}public sealed class ChangeSchoolClassCodeRequestValidator:AbstractValidator<ChangeSchoolClassCodeRequest>{public ChangeSchoolClassCodeRequestValidator()=>RuleFor(x=>x.Code).NotEmpty().MaximumLength(50).Matches("^[A-Za-z0-9]+(?:[-_][A-Za-z0-9]+)*$");}
